/*
 * A112230  Sequence of Chen primes of the form (x*n+1)*(y*n+1)-2 in the order
 *          generated by A112229.
 * https://oeis.org/A112230
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (A112229(n,1)*n+1)*(A112229(n,2)*n+1)-2
 * Range:     u8 n <= 4, u16 n <= 16, u32 n <= 16, u64 n <= 39, u128 n <= 39,
 *            big any n
 * Helpers:   isprime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/isprime_big.h"

seq_t a(idx_t n)
{
    uint64_t nn = (uint64_t)n;

    for (uint64_t x = 1; ; ++x) {
        /* p1 = x*n + 1 */
        seq_t p1 = (seq_t)x * (seq_t)nn + (seq_t)1;

        if (p1 == (seq_t)2)                /* ignore prime 2 */
            continue;
        if (!isprime_big(p1))              /* p1 must be prime */
            continue;

        for (uint64_t y = x + 1; ; ++y) {
            /* p2 = y*n + 1, insist y > x to avoid duplicates */
            seq_t p2 = (seq_t)y * (seq_t)nn + (seq_t)1;

            if (p2 == (seq_t)2)            /* ignore prime 2 */
                continue;
            if (!isprime_big(p2))          /* p2 must be prime */
                continue;

            seq_t prod = p1 * p2;          /* (p1)*(p2) */
            seq_t val  = prod - (seq_t)2;  /* candidate Chen prime */

            if (isprime_big(val))          /* val must itself be prime */
                return val;
        }
    }
}
